// Solution for Longest Substring Without Repeating Characters
function lengthOfLongestSubstring(s) {
  let set = new Set(), max = 0, l = 0;
  for (let r = 0; r < s.length; r++) {
    while (set.has(s[r])) {
      set.delete(s[l]);
      l++;
    }
    set.add(s[r]);
    max = Math.max(max, r - l + 1);
  }
  return max;
}

